                 ("Earned an award or recognition", ["won", "received", "merited", "secured", "collected", "took"], "Won Teacher of the Year in a district of 1,100 teachers"),
                 ("Earned money for the business", ["generated", "brought in", "made", "produced", "netted", "grossed"], "Brought in $62K in catering orders in a first year running a food truck"),
                 ("Earned a promotion", ["advanced", "rose", "moved up", "progressed", "stepped up", "climbed"], "Advanced from teller to assistant branch manager in 30 months"),
